def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([0, 0, 0]), fmt([3, 3, 5, 0, 0, 3, 1, 4]), fmt([1, 2, 3, 4, 5]), fmt([7, 6, 4, 3, 1]),
             fmt([1, 5]), fmt([5, 1]), fmt([1, 4, 2, 7, 3, 9]), fmt([2, 1, 2, 0, 1]), fmt([6, 1, 3, 2, 4, 7])]
    for n in (2, 3, 4, 5, 6, 7, 8, 10, 12):
        for _ in range(2):
            tests.append(fmt([rng.randint(0, 20) for _ in range(n)]))
    for _ in range(4):
        n = rng.randint(6, 13)
        tests.append(fmt([rng.choice([1, 2, 9, 10, 50]) for _ in range(n)]))
    n = 100000
    tests.append(fmt([rng.randint(0, 10**5) for _ in range(n)]))
    # zigzag with three big swings so that two transactions are strictly better than one
    big = []
    base = 0
    while len(big) < n:
        big.append(rng.randint(0, 100))
    for lo, hi in ((10000, 30000), (45000, 60000), (70000, 90000)):
        a = rng.randint(1000, 5000)
        for i in range(lo, hi):
            big[i] = a + (i - lo) * 3 // 2 if i < (lo + hi) // 2 else a + ((lo + hi) // 2 - lo) * 3 // 2 - (i - (lo + hi) // 2)
    tests.append(fmt(big))
    # random walk
    w = [50000]
    for _ in range(n - 1):
        w.append(min(10**5, max(0, w[-1] + rng.randint(-300, 300))))
    tests.append(fmt(w))
    tests.append(fmt([i for i in range(n)]))
    return tests
